2.2 Verificación de tipos
Python nos permite verificar el tipo de cualquier valor con la función type():

# Verificando tipos
print(type(150))           # &lt;class 'int'&gt;
print(type(3.75))          # &lt;class 'float'&gt;
print(type("Perú"))        # &lt;class 'str'&gt;
print(type(True))          # &lt;class 'bool'&gt;

&lt;class 'int'&gt;
&lt;class 'float'&gt;
&lt;class 'str'&gt;
&lt;class 'bool'&gt;

4.5 Dictionary comprehension

# Crear diccionarios con comprehension
# Sintaxis: {clave: valor for item in iterable}

# Ejemplo 1: Cuadrados
cuadrados_dict = {x: x**2 for x in range(6)}
print(f"Cuadrados: {cuadrados_dict}")

# Ejemplo 2: Mapeo de códigos
productos = ['A', 'B', 'C', 'D', 'E']
precios = [10, 15, 20, 25, 30]

catalogo = {prod: precio for prod, precio in zip(productos, precios)}
print(f"\nCatálogo: {catalogo}")

# Ejemplo 3: Filtrar diccionario
datos_economicos = {
    'pib': 242632,
    'poblacion': 33715471,
    'inflacion': 3.5,
    'desempleo': 7.2,
    'reservas': 74500
}

# Solo valores mayores a 100
grandes_valores = {k: v for k, v in datos_economicos.items() if v &gt; 100}
print(f"\nGrandes valores: {grandes_valores}")

Cuadrados: {0: 0, 1: 1, 2: 4, 3: 9, 4: 16, 5: 25}

Catálogo: {'A': 10, 'B': 15, 'C': 20, 'D': 25, 'E': 30}

Grandes valores: {'pib': 242632, 'poblacion': 33715471, 'reservas': 74500}

7.3 Búsqueda en estructuras anidadas

# Buscar en matriz
matriz_datos = [
    [10, 20, 30],
    [40, 50, 60],
    [70, 80, 90]
]

valor_buscar = 50
encontrado = False

for i, fila in enumerate(matriz_datos):
    for j, valor in enumerate(fila):
        if valor == valor_buscar:
            print(f"Valor {valor_buscar} encontrado en posición [{i}][{j}]")
            encontrado = True
            break
    if encontrado:
        break

if not encontrado:
    print(f"Valor {valor_buscar} no encontrado")

Valor 50 encontrado en posición [1][1]

9.3 Aplicaciones combinadas

# Validación de datos con límite de intentos
intentos_maximos = 3
intentos = 0

while intentos &lt; intentos_maximos:
    try:
        monto = float(input("Ingrese monto (positivo): "))

        if monto &lt; 0:
            print("Error: el monto debe ser positivo")
            intentos += 1
            continue

        if monto &gt; 100000:
            print("Advertencia: monto muy alto")
            confirmar = input("¿Desea continuar? (s/n): ")
            if confirmar.lower() != 's':
                continue

        print(f"Monto válido: S/ {monto:,.2f}")
        break

    except ValueError:
        print("Error: ingrese un número válido")
        intentos += 1

if intentos &gt;= intentos_maximos:
    print("\nNúmero máximo de intentos alcanzado")

6.1 Sintaxis if-elif-else

# Estructura básica
x = 10

if x &lt; 0:
    print("Negativo")
elif x == 0:
    print("Cero")
elif x &lt; 10:
    print("Positivo menor que 10")
else:
    print("10 o mayor")

10 o mayor

7.1 Estructura básica

# Condicional anidado simple
x = 10

if x &gt; 0:
    print("x es positivo")
    if x &gt; 5:
        print("x es mayor que 5")
    else:
        print("x es menor o igual a 5")
else:
    print("x es cero o negativo")

x es positivo
x es mayor que 5

7.3 Alternativa a anidamiento excesivo
Los condicionales muy anidados pueden dificultar la lectura. Es mejor usar elif:

# Evitar anidamiento excesivo
ingreso = 5000
credito = "bueno"
empleo = "estable"

# Mal: muy anidado
if ingreso &gt; 3000:
    if credito == "bueno":
        if empleo == "estable":
            print("Crédito aprobado")
        else:
            print("Crédito denegado: empleo inestable")
    else:
        print("Crédito denegado: mal historial")
else:
    print("Crédito denegado: ingreso bajo")

# Mejor: condiciones combinadas
if ingreso &lt;= 3000:
    print("Crédito denegado: ingreso bajo")
elif credito != "bueno":
    print("Crédito denegado: mal historial")
elif empleo != "estable":
    print("Crédito denegado: empleo inestable")
else:
    print("Crédito aprobado")

# Aún mejor: usar operadores lógicos
if ingreso &gt; 3000 and credito == "bueno" and empleo == "estable":
    print("Crédito aprobado")
else:
    print("Crédito denegado")

Crédito aprobado
Crédito aprobado
Crédito aprobado

9.2 Capturar excepciones específicas

# Capturar tipos específicos de errores
try:
    resultado = 10 / 0
except ZeroDivisionError:
    print("Error: división por cero")

try:
    lista = [1, 2, 3]
    print(lista[5])
except IndexError:
    print("Error: índice fuera de rango")

try:
    diccionario = {'a': 1, 'b': 2}
    print(diccionario['c'])
except KeyError:
    print("Error: clave no existe")

try:
    numero = int("texto")
except ValueError:
    print("Error: valor no numérico")

Error: división por cero
Error: índice fuera de rango
Error: clave no existe
Error: valor no numérico

5.1 Creación de diccionarios

# Diccionario vacío
pais_vacio = {}
print(type(pais_vacio))  # &lt;class 'dict'&gt;

# Diccionario con datos económicos de un país
peru = {
    'nombre': 'Perú',
    'pib': 242632,
    'poblacion': 33715471,
    'moneda': 'Sol',
    'codigo_iso': 'PER'
}
print(peru)

# Diccionario con diferentes tipos de valores
indicadores = {
    'pib': 242632,              # int
    'crecimiento': 2.7,          # float
    'moneda': 'PEN',             # string
    'emergente': True,           # boolean
    'sectores': ['Minería', 'Agricultura'],  # lista
    'comercio': {'exp': 63200, 'imp': 53800}  # diccionario anidado
}
print(indicadores)

